// test/governance/test-review-queue-handoff-dogfood.mjs
//
// CURRENT-LATEST-REVIEW-PRESENTATION-SEMANTICS-1 T20 — REAL dogfood: REAL
// formal review generations flow through the production review lifecycle
//（runStateDrivenCloseout with the default surface deliverer）; every
// completion PUBLISHES to Current immediately — no verdict gates, no manual
// clearing, no promotion.
//
// Real = the bundles are generated by the PRODUCTION closeout gate against a
// real repo（collectRepoFacts + runStateDrivenCloseout）— not synthetic
// renderReviewBundle fixtures. The surface is env-isolated（AUTOLOOP_REVIEW_
// SURFACE / ARCHIVE / QUEUE）so the real Desktop inbox is never touched.
//
// Scenario:
//   1. card A closes out -> Current = A
//   2. card B closes out while A is unresolved -> Current = B（publish-always;
//      A stays durable PENDING in the ledger）
//   3. external reviewer applies PASS to A -> ledger REVIEWED + archived;
//      Current UNCHANGED（verdict lifecycle never controls presentation）
//   4. Latest points at B（newest generated）
//
// Run: node --test test/governance/test-review-queue-handoff-dogfood.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  runStateDrivenCloseout,
  collectRepoFacts,
  applyExternalReviewVerdict,
  rotateExternalReviewSurface,
  readExternalReviewDeliveryRecord,
  writeExternalReviewDeliveryRecord,
} from "../../src/governance/review-bundle.mjs";
import { CLOSEOUT_STATE_SCHEMA } from "../../src/governance/closeout-state.mjs";
import { writeCloseoutState, closeoutStatePath } from "../../src/governance/closeout-state.mjs";
import { reviewQueueStatus, readLatestPointer } from "../../src/governance/review-queue.mjs";

const REPO_A = "/private/tmp/autoloop";
const ROOT = `${tmpdir()}/revq-dogfood-${process.pid}`;
const SURFACE = join(ROOT, "Current");
const ARCHIVE = join(ROOT, "Archive");
const QUEUE = join(ROOT, "Queue");
const OUT = join(ROOT, "out");

const facts = collectRepoFacts(REPO_A);
const shaFile = (p) => createHash("sha256").update(readFileSync(p)).digest("hex");

const passGraph = (cardId) => ({
  executionId: `revq-dogfood-${cardId}`,
  final: "PASS",
  holdCode: null,
  reason: null,
  scheduler: { verdict: "PASS", order: ["W1"], statuses: { W1: "passed" }, skipped: [] },
  nodeResults: [
    {
      nodeId: "W1", phaseExecutionId: `exec_${cardId}`, taskType: "write", dependencies: [],
      final: "PASS", attempt: 0, reason: null, startedAt: 1, completedAt: 2,
      cleanup: { worktreeRevoked: false },
      subagentResult: { status: "PASS", testResults: { passed: 1, failed: 0, total: 1 }, testsExecuted: ["self-test"] },
    },
  ],
  transitions: [{ phaseId: "W1", final: "PASS", attempt: 0, lifecycleTransitions: [{ phase: "reviewer_verdict", attempt: 0, verdict: "PASS", recommended_next_action: "STOP" }] }],
});

function closeoutState(cardId) {
  return {
    schema: CLOSEOUT_STATE_SCHEMA,
    task: { cardId, cardTitle: `REVQ dogfood ${cardId}`, cardType: "implementation" },
    requiresReview: true,
    reviewRequiredAt: "2026-08-16T00:00:00.000Z",
    outDir: join(OUT, cardId),
    authorizedScope: ["src/governance/review-bundle.mjs", "src/governance/review-queue.mjs"],
    unauthorizedScope: ["commit", "push", "merge", "seal"],
    designDecisions: ["queue handoff dogfood"],
    objective: `${cardId}: real two-generation queue dogfood`,
    negativeCases: ["no manual Current clearing"],
    regression: [{ suite: "test:governance", tests: 1, pass: 1, fail: 0 }],
    regressionSummary: "focused",
    recommendedNextStep: "external review",
  };
}

async function closeoutCard(cardId) {
  const state = closeoutState(cardId);
  const stPath = closeoutStatePath(state.outDir);
  mkdirSync(state.outDir, { recursive: true });
  writeCloseoutState({ path: stPath, state });
  return runStateDrivenCloseout({
    statePath: stPath,
    graphResult: passGraph(cardId),
    repoPath: REPO_A,
    cwd: REPO_A,
    outDir: state.outDir,
    timeoutMs: 15000,
    surfaceDir: SURFACE,
  });
}

function surfaceCard() {
  const p = join(SURFACE, "delivery.json");
  if (!existsSync(p)) return null;
  const rec = readExternalReviewDeliveryRecord(p);
  return rec.ok ? { cardId: rec.cardId, state: rec.state } : null;
}

test("T20. two REAL formal review generations: second publishes immediately; verdict on the first never changes Current", { timeout: 60000 }, async () => {
  rmSync(ROOT, { recursive: true, force: true });
  for (const d of [SURFACE, ARCHIVE, QUEUE, OUT]) mkdirSync(d, { recursive: true });
  process.env.AUTOLOOP_REVIEW_SURFACE = SURFACE;
  process.env.AUTOLOOP_REVIEW_ARCHIVE = ARCHIVE;
  process.env.AUTOLOOP_REVIEW_QUEUE = QUEUE;
  try {
    const cardA = "REVQ-DOGFOOD-A";
    const cardB = "REVQ-DOGFOOD-B";

    // 1. card A formal review generation -> Current = A.
    const ra = await closeoutCard(cardA);
    assert.equal(ra.final, "PASS", `A closeout PASS (${ra.reason ?? ""})`);
    assert.equal(ra.externalReview.delivery.method, "external-review-surface", "A delivered to Current");
    assert.equal(surfaceCard()?.cardId, cardA, "A is Current");
    const bundleASha = shaFile(join(SURFACE, "review-bundle.txt"));

    // 2. card B formal review generation while A is UNRESOLVED -> Current = B
    //    immediately（publish-always; no verdict gate, no manual clearing）.
    const rb = await closeoutCard(cardB);
    assert.equal(rb.final, "PASS", `B closeout PASS (${rb.reason ?? ""})`);
    assert.equal(rb.externalReview.delivery.method, "external-review-surface", "B published to Current");
    assert.equal(surfaceCard()?.cardId, cardB, "B is Current (A unresolved)");
    assert.equal(shaFile(join(SURFACE, "review-bundle.txt")), shaFile(rb.bundlePath), "B bytes verbatim");
    const st1 = reviewQueueStatus(SURFACE);
    assert.equal(st1.pending.length, 2, "A and B both pending");
    assert.equal(st1.queue.entries.find((e) => e.cardId === cardA).isLatestPresented, false, "A not presented");
    assert.equal(st1.queue.entries.find((e) => e.cardId === cardB).isLatestPresented, true, "B presented");
    const latest1 = readLatestPointer(SURFACE);
    assert.equal(latest1.latest.cardId, cardB, "Latest = newest generated (B)");

    // 3. external reviewer applies PASS to A -> ledger REVIEWED + archived;
    //    Current UNCHANGED（card I: verdict lifecycle never controls the
    //    presentation pointer）.
    const rot = rotateExternalReviewSurface({
      surfaceDir: SURFACE, archiveDir: ARCHIVE,
      cardId: cardA, identity: ra.externalReview.delivery.reviewBundleIdentity, verdict: "PASS",
    });
    assert.equal(rot.ok, true, `rotate ok (${rot.reason ?? ""})`);
    assert.equal(rot.promoted, null, "no promotion — presentation is verdict-independent");

    // 4. verification: Current = B unchanged, bytes verbatim, A REVIEWED.
    const occ = surfaceCard();
    assert.equal(occ.cardId, cardB, "B still Current after A's PASS");
    assert.equal(shaFile(join(SURFACE, "review-bundle.txt")), shaFile(rb.bundlePath), "B bundle bytes verbatim (no regeneration)");
    const st2 = reviewQueueStatus(SURFACE);
    assert.equal(st2.pending.length, 1, "only B pending");
    assert.equal(st2.queue.entries.find((e) => e.cardId === cardA).state, "REVIEWED", "A reviewed in ledger");
    assert.equal(st2.current?.cardId, cardB, "presented = B");
    const latest2 = readLatestPointer(SURFACE);
    assert.equal(latest2.latest.cardId, cardB, "Latest remains B（newest generated）");
    const archives = readdirSync(ARCHIVE);
    assert.equal(archives.filter((f) => f.includes(cardA) && f.includes("PASS") && f.endsWith("review-bundle.txt")).length, 1, "A archived bundle exists");
    const aArch = archives.find((f) => f.includes(cardA) && f.endsWith("review-bundle.txt"));
    assert.equal(shaFile(join(ARCHIVE, aArch)), bundleASha, "A archived bundle bytes preserved");

    console.log(`dogfood-ok: A=${cardA} B=${cardB} current=${occ.cardId} pending=${st2.pending.length} latest=${latest2.latest.cardId}`);
  } finally {
    delete process.env.AUTOLOOP_REVIEW_SURFACE;
    delete process.env.AUTOLOOP_REVIEW_ARCHIVE;
    delete process.env.AUTOLOOP_REVIEW_QUEUE;
    rmSync(ROOT, { recursive: true, force: true });
  }
});
